service.method:

INSERT INTO SGWAH 
	( 
	    HOUSE_CODE 
	  , COMPANY_CODE 
	  , LINE_TYPE 
	  , APP_TYPE 
	  , CODE 
	  , LINE_TYPE_NAME 
	  , ADD_DATE 
	  , ADD_TIME 
	  , ADD_USER_ID 
	  , CHANGE_DATE 
	  , CHANGE_TIME 
	  , CHANGE_USER_ID  
	) 
VALUES 
	( 
	    ${HOUSE_CODE} 
	  , ${COMPANY_CODE} 
	  , ${LINE_TYPE} 
	  , ${APP_TYPE} 
	  , ${CODE} 
	  , ${LINE_TYPE_NAME} 
	  , ${current.date} 
	  , ${current.time} 
	  , ${session.ID} 
	  , ${current.date} 
	  , ${current.time} 
	  , ${session.ID}  
	)


INSERT INTO SGWAD 
	( 
	    HOUSE_CODE
	  , COMPANY_CODE
	  , LINE_TYPE
	  , APP_TYPE
	  , CODE
	  , LINE_SEQ
	  , USER_ID
	  , APP_USER_AMT
	  , ADD_DATE
	  , ADD_TIME
	  , ADD_USER_ID
	  , CHANGE_DATE
	  , CHANGE_TIME
	  , CHANGE_USER_ID
	  , APP_METHOD
	) 
VALUES 
	( 
	    ${HOUSE_CODE} 
	  , ${COMPANY_CODE} 
	  , ${LINE_TYPE}
	  , ${APP_TYPE}
	  , ${CODE}
	  , ${LINE_SEQ}
	  , ${USER_ID}
	  , '0'
	  , ${current.date} 
	  , ${current.time} 
	  , ${session.ID} 
	  , ${current.date} 
	  , ${current.time} 
	  , ${session.ID} 
	  , ${APP_METHOD}
	)


DELETE FROM SGWAH 
 WHERE HOUSE_CODE = ${HOUSE_CODE} 
   AND COMPANY_CODE = ${COMPANY_CODE} 
   AND LINE_TYPE = ${LINE_TYPE} 
   AND APP_TYPE = ${APP_TYPE} 
   AND CODE = ${CODE}


DELETE FROM SGWAD 
 WHERE HOUSE_CODE = ${HOUSE_CODE} 
   AND COMPANY_CODE = ${COMPANY_CODE} 
   AND LINE_TYPE = ${LINE_TYPE} 
   AND APP_TYPE = ${APP_TYPE} 
   AND CODE = ${CODE}
